import React from 'react';
import { useOutletContext, Outlet, useLocation } from 'react-router-dom';
import RealtimeWorkspace from '../../components/RealtimeWorkspace';
import ProjectNavbar from '../../components/ProjectNavbar';

const WorkspacePage = () => {
  const context = useOutletContext();
  const location = useLocation();

  // This logic checks if the current URL is exactly "/work"
  // If it is anything else (like "/work/p1"), isDashboard becomes false.
  const isDashboard = location.pathname === '/work';

  return (
    <div className="h-full">
      <ProjectNavbar 
        basePath="work" 
        links={["Streaming", "Collab", "Nodes", "Logs"]} 
      />
      
      <div className="p-8">
         {/* Only show RealtimeWorkspace if we are on the main dashboard view */}
         {isDashboard && <RealtimeWorkspace />}
         
         {/* The Outlet renders P1, P2, etc. when the URL matches their path */}
         <Outlet context={context} /> 
      </div>
    </div>
  );
};

export default WorkspacePage;
